// PostgreSQL: 40001 serialization_failure, 40P01 deadlock_detected
const RETRYABLE = new Set(['40001', '40P01'])
for (let attempt = 1; ; attempt++) {
  try {
    return await db.transaction(tx => runTransfer(tx, from, to, amount))
  } catch (err) {
    if (!RETRYABLE.has(err.code) || attempt === 5) throw err
    await sleep(Math.random() * 20 * 2 ** attempt) // jittered backoff
  }
}

